SELECT  FROM fm_notification
WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR} AND RECIPIENT_ACCOUNT = #{recipientAccount,jdbcType=VARCHAR} AND CHANNEL_TYPE = 'IN_APP'
ORDER BY CDATE DESC LIMIT #{limit,jdbcType=INTEGER}

mapper.update:
UPDATE fm_notification
   SET DELIVERY_STATUS = 'SENT', SENT_DATE = #{sentDate,jdbcType=TIMESTAMP},
       UUSERID = 'mail-sync', UDATE = #{sentDate,jdbcType=TIMESTAMP}
 WHERE TENANT_ID = #{tenantId,jdbcType=VARCHAR}
   AND NOTIFICATION_ID = #{notificationId,jdbcType=VARCHAR}
   AND PROVIDER_MESSAGE_ID = #{providerMessageId,jdbcType=VARCHAR}
   AND CHANNEL_TYPE = 'EMAIL' AND DELIVERY_STATUS = 'PENDING'
